import heapq


def _round(n, mode):
    if mode == "half_up":
        return (n + 5000) // 10000
    return n // 10000


def _ledger(data, priority, tax_base):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        if priority == "sequence_first":
            key = (seq, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = raw if tax_base == "original" else net
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _ledger_solver(priority, tax_base):
    return lambda data: _ledger(data, priority, tax_base)


def _resolve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    rows = {name: {row["version"]: row for row in entries}
            for name, entries in packages.items()}
    domains = [[-1] + sorted(rows[name]) for name in names]
    best_key = None
    best = None

    for values in product(*domains):
        installed = dict(zip(names, values))
        ok = True
        graph = {name: [] for name, version in installed.items() if version != -1}
        for name, bounds in roots.items():
            version = installed[name]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                ok = False
                break
        if not ok:
            continue
        for name, version in installed.items():
            if version == -1:
                continue
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                ok = False
                break
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed[target]
                if target_version == -1 or not dep["min"] <= target_version <= dep["max"]:
                    ok = False
                    break
                graph[name].append(target)
            if not ok:
                break
        if not ok:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        key = tuple(values)
        if best_key is None or key < best_key:
            best_key = key
            best = {name: version for name, version in installed.items() if version != -1}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    candidates = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(candidates, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bits = {node: sum(1 << i for i, value in enumerate(required) if value == node)
            for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    state = (data["source"], bits[data["source"]], data["coupons"])
    distances = {state: start}
    queue = [(start, state[0], state[1], state[2])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        current = (node, mask, remaining)
        if distances.get(current) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits[next_node]
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


